3	/// Where the range figure came from and how much to trust it.
4	///
5	/// The community server adapter does not return predictions at all, so
6	/// `.missing` is the default case in practice — the interface has to present it
7	/// as normal, not as a failure.
8	enum NinebotRangeEstimateQuality: Equatable {
9	    /// Server returned a prediction but says it fell back to its default
10	    /// algorithm because it lacked samples.
11	    case serverDefault
12	    /// Server algorithm, accuracy at or above the confidence threshold.
13	    case serverConfident(accuracy: Double)
14	    /// Server algorithm, still calibrating.
15	    case serverCalibrating
16	    /// Server responded but gave no usable algorithmic range.
17	    case serverUnavailable
18	    /// Server returned no prediction at all.
19	    case missing
20	}
21	
22	/// Where the accuracy percentage itself came from.
23	enum NinebotRangeAccuracyDetail: Equatable {
24	    /// Measured against rides that have since completed.
25	    case measured(verifiedCount: Int)
26	    /// The server's own algorithmic figure.
27	    case algorithmic(sampleCount: Int)
28	    /// Prediction present but no samples behind it.
29	    case insufficientSamples
30	    /// No prediction at all.
31	    case noPrediction
32	}
33	
34	/// What the displayed range estimate is actually based on.
35	enum NinebotLocalEstimateBasis: Equatable {
36	    /// Server blends the official estimate with observed rides.
37	    case personalized(sampleCount: Int?)
38	    /// Server's default algorithm.
39	    case serverDefault(sampleCount: Int?)
40	    /// No usable server prediction; showing the vehicle's own figure.
41	    case missing
42	}
43	
44	extension NinebotVehicleState {
45	
46	    /// Accuracy at or above this reads as trustworthy rather than calibrating.
47	    static let rangeConfidenceThreshold = 0.82
48	
49	    // Server contract values. Naming them keeps the comparisons out of the
50	    // middle of display logic.
51	    static let accuracySourceMeasured = "measured"
52	    static let rangeSourceDefault = "default"
53	    static let rangeSourcePersonalized = "personalized"
54	    static let rangeSourcePersonalizedBlend = "personalized_blend"
55	
56	    var rangeEstimateQuality: NinebotRangeEstimateQuality {
57	        guard usesServerAlgorithmEstimate else {
58	            return serverPrediction == nil ? .missing : .serverUnavailable
59	        }
60	        if serverPrediction?.range.source == Self.rangeSourceDefault {
61	            return .serverDefault
62	        }
63	        if let accuracy = rangeEstimateAccuracy, accuracy >= Self.rangeConfidenceThreshold {
64	            return .serverConfident(accuracy: accuracy)
65	        }
66	        return .serverCalibrating
67	    }
68	
69	    var rangeAccuracyDetail: NinebotRangeAccuracyDetail {
70	        guard let range = serverPrediction?.range else { return .noPrediction }
71	        guard let sampleCount = range.sampleCount, sampleCount > 0 else {
72	            return .insufficientSamples
73	        }
74	        if range.accuracySource == Self.accuracySourceMeasured {
75	            return .measured(verifiedCount: range.measuredSampleCount ?? sampleCount)
76	        }
77	        return .algorithmic(sampleCount: sampleCount)
78	    }
79	
80	    var localEstimateBasis: NinebotLocalEstimateBasis {
81	        guard let range = serverPrediction?.range,
82	              let estimatedRange = range.estimatedRange,
83	              estimatedRange >= 0 else {
84	            return .missing
85	        }
86	        switch range.source ?? "" {
87	        case Self.rangeSourcePersonalized, Self.rangeSourcePersonalizedBlend:
88	            return .personalized(sampleCount: range.sampleCount)
89	        default:
90	            return .serverDefault(sampleCount: range.sampleCount)
91	        }
92	    }
93	
94	    /// Whether the server supplied a usable algorithmic range.
95	    var usesServerAlgorithmEstimate: Bool {
96	        guard let estimatedRange = serverPrediction?.range.estimatedRange,
97	              estimatedRange >= 0 else {
98	            return false
99	        }
100	        return true
101	    }
102	}
