736	private struct AppleReverseGeocoder {
737	    func reverseGeocode(latitude: Double, longitude: Double) async throws -> String {
738	        let location = CLLocation(latitude: latitude, longitude: longitude)
739	        guard let request = MKReverseGeocodingRequest(location: location) else {
740	            throw AppleGeocodingError.invalidResponse
741	        }
742	        request.preferredLocale = Locale(identifier: "zh_CN")
743	
744	        let mapItems = try await request.mapItems
745	        let address = Self.addressText(from: mapItems.first)
746	        guard !address.isEmpty else {
747	            throw AppleGeocodingError.invalidResponse
748	        }
749	        return address
750	    }
751	
752	    private static func addressText(from mapItem: MKMapItem?) -> String {
753	        guard let mapItem else { return "" }
754	        let candidates = [
755	            mapItem.addressRepresentations?.fullAddress(includingRegion: true, singleLine: true),
756	            mapItem.address?.fullAddress,
757	            mapItem.address?.shortAddress,
758	            mapItem.name
759	        ]
760	
761	        return candidates
762	            .compactMap { $0?.trimmingCharacters(in: .whitespacesAndNewlines) }
763	            .first { !$0.isEmpty } ?? ""
764	    }
765	}

